module governor_party_converter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    input wire [7:0] m,\n    input wire [99:0] initial_parties,\n    input wire [9:0] friendship_a,\n    input wire [9:0] friendship_b,\n    output reg [7:0] min_months,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] STATE_IDLE         = 4'd0;\n    localparam [3:0] STATE_LOAD_GRAPH   = 4'd1;\n    localparam [3:0] STATE_CHECK_MONO   = 4'd2;\n    localparam [3:0] STATE_BFS_INIT     = 4'd3;\n    localparam [3:0] STATE_BFS_LOOP     = 4'd4;\n    localparam [3:0] STATE_UPDATE_STATE = 4'd5;\n    localparam [3:0] STATE_DONE         = 4'd6;\n\n    // Graph storage\n    reg [7:0] adj_matrix [0:15][0:15];\n    reg [7:0] current_parties [0:15];\n    reg [3:0] graph_size;\n    reg [3:0] bfs_queue [0:15];\n    reg [3:0] queue_head;\n    reg [3:0] queue_tail;\n    reg [3:0] component_nodes [0:15];\n    reg [3:0] component_count;\n    reg [3:0] node_index;\n    reg [1:0] current_lobbyist;\n    reg [7:0] month_count;\n    reg [3:0] flip_start_node;\n    reg [15:0] visited_mask;\n    reg [15:0] all_same_mask;\n    reg [3:0] state;\n    reg [3:0] next_state;\n    reg [15:0] timeout_counter;\n\n    integer i, j;\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            min_months <= 8'hFF;\n            done <= 1'b0;\n            timeout_counter <= 16'd0;\n            \n            // Initialize arrays\n            for (i = 0; i < 16; i = i + 1) begin\n                current_parties[i] <= 8'd0;\n                bfs_queue[i] <= 4'd0;\n                component_nodes[i] <= 4'd0;\n                for (j = 0; j < 16; j = j + 1) begin\n                    adj_matrix[i][j] <= 8'd0;\n                end\n            end\n        end else begin\n            state <= next_state;\n            timeout_counter <= timeout_counter + 16'd1;\n            if (timeout_counter >= 16'hFFF0) begin\n                state <= STATE_DONE;\n                min_months <= 8'hFF;\n                done <= 1'b1;\n            end\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            STATE_IDLE: begin\n                if (start) next_state = STATE_LOAD_GRAPH;\n            end\n\n            STATE_LOAD_GRAPH: next_state = STATE_CHECK_MONO;\n\n            STATE_CHECK_MONO: begin\n                next_state = (all_same_mask == 16'hFFFF) ? STATE_DONE : STATE_BFS_INIT;\n            end\n\n            STATE_BFS_INIT: next_state = STATE_BFS_LOOP;\n\n            STATE_BFS_LOOP: begin\n                if (queue_head == queue_tail) next_state = STATE_UPDATE_STATE;\n            end\n\n            STATE_UPDATE_STATE: begin\n                if ((month_count > 8'd16) || (all_same_mask == 16'hFFFF)) begin\n                    next_state = STATE_DONE;\n                end else begin\n                    next_state = STATE_BFS_INIT;\n                end\n            end\n\n            STATE_DONE: next_state = STATE_DONE;\n\n            default: next_state = STATE_IDLE;\n        endcase\n    end\n\n    // Datapath logic\n    always @(posedge clk) begin\n        done <= 1'b0;\n\n        if (state == STATE_LOAD_GRAPH) begin\n            graph_size <= (n > 8'd16) ? 4'd15 : n[3:0];\n            current_lobbyist <= 2'd0;\n            month_count <= 8'd0;\n\n            for (i = 0; i < 16; i = i + 1) begin\n                current_parties[i] <= initial_parties[i];\n                for (j = 0; j < 16; j = j + 1) begin\n                    adj_matrix[i][j] <= (i == j) ? 8'd1 : 8'd0;\n                end\n            end\n        end\n\n        else if (state == STATE_CHECK_MONO) begin\n            all_same_mask <= 16'hFFFF;\n            for (i = 1; i < graph_size; i = i + 1) begin\n                if (current_parties[i] != current_parties[0]) begin\n                    all_same_mask <= 16'h0000;\n                end\n            end\n        end\n\n        else if (state == STATE_BFS_INIT) begin\n            queue_head <= 4'd0;\n            queue_tail <= 4'd0;\n            visited_mask <= 16'd0;\n            component_count <= 4'd0;\n            flip_start_node <= 4'd0;\n\n            for (i = 0; i < graph_size; i = i + 1) begin\n                if (!visited_mask[i] && (current_parties[i] != current_lobbyist)) begin\n                    flip_start_node <= i;\n                    break;\n                end\n            end\n        end\n\n        else if (state == STATE_BFS_LOOP && queue_head < queue_tail) begin\n            component_nodes[component_count] <= bfs_queue[queue_head];\n            component_count <= component_count + 4'd1;\n\n            for (j = 0; j < graph_size; j = j + 1) begin\n                if (adj_matrix[bfs_queue[queue_head]][j] && \n                   !visited_mask[j] && \n                   (current_parties[j] == current_parties[bfs_queue[queue_head]])) begin\n\n                    bfs_queue[queue_tail] <= j;\n                    queue_tail <= queue_tail + 4'd1;\n                    visited_mask[j] <= 1'b1;\n                end\n            end\n            queue_head <= queue_head + 4'd1;\n        end\n\n        else if (state == STATE_UPDATE_STATE) begin\n            for (i = 0; i < component_count; i = i + 1) begin\n                current_parties[component_nodes[i]] <= current_lobbyist;\n            end\n            month_count <= month_count + 8'd1;\n            current_lobbyist <= ~current_lobbyist;\n        end\n\n        else if (state == STATE_DONE) begin\n            min_months <= month_count;\n            done <= 1'b1;\n        end\n    end\nendmodule